package com.delivery.platform.orders.infrastructure;
import com.delivery.platform.common.ApiException;import com.delivery.platform.delivery.application.DeliveryCoverageService;import com.delivery.platform.orders.application.OrdersRepository;import com.delivery.platform.orders.application.OrdersRepository.*;import com.delivery.platform.orders.domain.OrderModels.*;import com.delivery.platform.orders.domain.OrderStatus;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;import java.math.*;import java.sql.*;import java.util.*;
@Repository public class JdbcOrdersRepository implements OrdersRepository {private final JdbcClient db;public JdbcOrdersRepository(JdbcClient db){this.db=db;}
 public Optional<Cart> activeCart(UUID t,UUID c){return db.sql("select * from carts where tenant_id=:t and customer_id=:c and status='ACTIVE'").param("t",t).param("c",c).query((r,n)->mapCart(r,t,c)).optional();}
 public Cart cart(UUID t,UUID c,UUID id){return db.sql("select * from carts where id=:i and tenant_id=:t and customer_id=:c and status='ACTIVE'").param("i",id).param("t",t).param("c",c).query((r,n)->mapCart(r,t,c)).optional().orElseThrow(()->missing("CART_NOT_FOUND","Carrito no encontrado"));}
 public Cart createCart(UUID t,UUID c,UUID m,UUID b,String currency){UUID id=UUID.randomUUID();db.sql("insert into carts(id,tenant_id,customer_id,merchant_id,branch_id,currency) values(:i,:t,:c,:m,:b,:u)").param("i",id).param("t",t).param("c",c).param("m",m).param("b",b).param("u",currency).update();return cart(t,c,id);}
 public void addItem(UUID t,UUID cart,UUID p,String name,int q,BigDecimal base,List<OptionSelection> options,String signature,String notes){UUID item=UUID.randomUUID();BigDecimal extra=options.stream().map(OptionSelection::priceAdjustment).reduce(BigDecimal.ZERO,BigDecimal::add),unit=base.add(extra);db.sql("insert into cart_items(id,tenant_id,cart_id,product_id,product_name,quantity,base_unit_price,options_total,unit_price,subtotal,selection_signature,notes) values(:i,:t,:c,:p,:n,:q,:b,:x,:u,:s,:g,:o)").param("i",item).param("t",t).param("c",cart).param("p",p).param("n",name).param("q",q).param("b",base).param("x",extra).param("u",unit).param("s",unit.multiply(BigDecimal.valueOf(q))).param("g",signature).param("o",notes).update();for(OptionSelection option:options)db.sql("insert into cart_item_options(tenant_id,cart_item_id,option_group_id,option_item_id,group_name,item_name,price_adjustment) values(:t,:c,:g,:i,:gn,:n,:p)").param("t",t).param("c",item).param("g",option.groupId()).param("i",option.itemId()).param("gn",option.groupName()).param("n",option.itemName()).param("p",option.priceAdjustment()).update();}
 public void updateItem(UUID t,UUID cart,UUID item,int q,String notes){int n=db.sql("update cart_items set quantity=:q,subtotal=unit_price*:q,notes=:o,updated_at=now() where id=:i and tenant_id=:t and cart_id=:c").param("q",q).param("o",notes).param("i",item).param("t",t).param("c",cart).update();if(n==0)throw missing("CART_ITEM_NOT_FOUND","Producto no encontrado en el carrito");}
 public void deleteItem(UUID t,UUID cart,UUID item){int n=db.sql("delete from cart_items where id=:i and tenant_id=:t and cart_id=:c").param("i",item).param("t",t).param("c",cart).update();if(n==0)throw missing("CART_ITEM_NOT_FOUND","Producto no encontrado en el carrito");}
 public void clearCart(UUID t,UUID cart){db.sql("delete from cart_items where tenant_id=:t and cart_id=:c").param("t",t).param("c",cart).update();db.sql("update carts set subtotal=0,discount=0,tax=0,delivery_fee=0,total=0,updated_at=now() where id=:c and tenant_id=:t").param("c",cart).param("t",t).update();}
 public void saveTotals(UUID t,UUID c,OrderSummary x){db.sql("update carts set subtotal=:s,discount=:d,tax=:x,delivery_fee=:f,total=:o,updated_at=now() where id=:c and tenant_id=:t").param("s",x.subtotal()).param("d",x.discount()).param("x",x.tax()).param("f",x.deliveryFee()).param("o",x.total()).param("c",c).param("t",t).update();}
 public ProductSnapshot product(UUID t,UUID m,UUID b,UUID p){String sql="select p.id,p.merchant_id,p.name,coalesce(bp.override_price,p.base_price) price,p.currency,coalesce(p.tax_rate,0) tax_rate,p.track_inventory,coalesce(bp.stock_quantity,p.stock_quantity) stock,p.available product_available,coalesce(bp.available,true) branch_available,p.status product_status,m.status merchant_status,b.status branch_status from products p join merchants m on m.id=p.merchant_id and m.tenant_id=p.tenant_id join branches b on b.id=:b and b.merchant_id=p.merchant_id and b.tenant_id=p.tenant_id left join branch_products bp on bp.product_id=p.id and bp.branch_id=b.id where p.id=:p and p.tenant_id=:t and p.merchant_id=:m";return db.sql(sql).param("b",b).param("p",p).param("t",t).param("m",m).query((r,n)->new ProductSnapshot(r.getObject("id",UUID.class),r.getObject("merchant_id",UUID.class),r.getString("name"),r.getBigDecimal("price"),r.getString("currency"),r.getBigDecimal("tax_rate"),r.getBoolean("track_inventory"),r.getBigDecimal("stock"),r.getBoolean("product_available"),r.getBoolean("branch_available"),r.getString("product_status"),r.getString("merchant_status"),r.getString("branch_status"))).optional().orElseThrow(()->missing("PRODUCT_NOT_FOUND","Producto no encontrado"));}
 public List<OptionGroupSnapshot> optionGroups(UUID t,UUID product){return db.sql("select g.* from option_groups g join product_option_groups pg on pg.option_group_id=g.id where pg.product_id=:p and g.tenant_id=:t and g.active order by pg.sort_order").param("p",product).param("t",t).query((r,n)->{UUID group=r.getObject("id",UUID.class);List<OptionSelection> items=db.sql("select id,name,price_adjustment from option_items where tenant_id=:t and option_group_id=:g and active and available order by sort_order,name").param("t",t).param("g",group).query((x,j)->new OptionSelection(group,x.getObject("id",UUID.class),r.getString("name"),x.getString("name"),x.getBigDecimal("price_adjustment"))).list();return new OptionGroupSnapshot(group,r.getString("name"),r.getString("selection_type"),r.getBoolean("required"),r.getInt("minimum_selections"),(Integer)r.getObject("maximum_selections"),items);}).list();}
 public DeliveryAddress address(UUID t,UUID c,UUID id){return db.sql("select * from delivery_addresses where id=:i and tenant_id=:t and customer_id=:c and active").param("i",id).param("t",t).param("c",c).query((r,n)->mapAddress(r)).optional().orElseThrow(()->missing("ADDRESS_NOT_FOUND","Dirección no encontrada"));}
 public List<DeliveryAddress> addresses(UUID t,UUID c){return db.sql("select * from delivery_addresses where tenant_id=:t and customer_id=:c and active order by created_at desc").param("t",t).param("c",c).query((r,n)->mapAddress(r)).list();}
 public DeliveryAddress createAddress(UUID t,UUID c,DeliveryAddress a){UUID id=UUID.randomUUID();db.sql("insert into delivery_addresses(id,tenant_id,customer_id,label,recipient_name,phone,address_line,district,province,department,country_code,postal_code,latitude,longitude,reference) values(:i,:t,:c,:l,:n,:p,:a,:d,:v,:e,:o,:z,:x,:y,:r)").param("i",id).param("t",t).param("c",c).param("l",a.label()).param("n",a.recipientName()).param("p",a.phone()).param("a",a.addressLine()).param("d",a.district()).param("v",a.province()).param("e",a.department()).param("o",a.countryCode()).param("z",a.postalCode()).param("x",a.latitude()).param("y",a.longitude()).param("r",a.reference()).update();return address(t,c,id);}
 public Order createOrder(UUID t,UUID customer,Cart c,UUID address,String notes,DeliveryCoverageService.Quote q){UUID id=UUID.randomUUID();String number="ORD-"+System.currentTimeMillis()+"-"+id.toString().substring(0,6).toUpperCase();db.sql("insert into orders(id,tenant_id,order_number,customer_id,merchant_id,branch_id,delivery_address_id,status,payment_status,subtotal,discount,tax,delivery_fee,total,currency,notes,delivery_address_text,delivery_latitude,delivery_longitude,delivery_reference,delivery_instructions,delivery_distance_km,delivery_base_fee,delivery_fee_per_km,delivery_minimum_fee,delivery_maximum_fee,delivery_free_threshold,delivery_free_applied,delivery_fallback_applied,delivery_zone_id,delivery_quote_created_at,eta_preparation_minutes,eta_assignment_minutes,eta_courier_to_merchant_minutes,eta_merchant_to_customer_minutes,eta_minimum_minutes,eta_maximum_minutes) select :i,:t,:n,:c,:m,:b,:a,'PENDING','PENDING',:s,:d,:x,:f,:o,:u,:z,coalesce(formatted_address,address_line),latitude,longitude,reference,delivery_instructions,:dk,:bf,:pk,:mn,:mx,:ft,:fa,:fb,:zi,:qa,:ep,:ea,:ec,:ed,:emin,:emax from delivery_addresses where id=:a and tenant_id=:t and customer_id=:c and active").param("i",id).param("t",t).param("n",number).param("c",customer).param("m",c.merchantId()).param("b",c.branchId()).param("a",address).param("s",c.subtotal()).param("d",c.discount()).param("x",c.tax()).param("f",c.deliveryFee()).param("o",c.total()).param("u",c.currency()).param("z",notes).param("dk",q==null?null:q.distanceKm()).param("bf",q==null?null:q.baseFee()).param("pk",q==null?null:q.feePerKm()).param("mn",q==null?null:q.minimumFee()).param("mx",q==null?null:q.maximumFee()).param("ft",q==null?null:q.freeDeliveryThreshold()).param("fa",q!=null&&q.freeDeliveryApplied()).param("fb",q!=null&&q.fallbackApplied()).param("zi",q==null?null:q.zoneId()).param("qa",q==null?null:java.time.OffsetDateTime.ofInstant(q.quotedAt(),java.time.ZoneOffset.UTC)).param("ep",q==null?null:q.preparationMinutes()).param("ea",q==null?null:q.assignmentMinutes()).param("ec",q==null?null:q.courierToMerchantMinutes()).param("ed",q==null?null:q.merchantToCustomerMinutes()).param("emin",q==null?null:q.minimumEstimatedMinutes()).param("emax",q==null?null:q.maximumEstimatedMinutes()).update();db.sql("insert into order_items(id,tenant_id,order_id,product_id,product_name,quantity,unit_price,subtotal,notes) select gen_random_uuid(),tenant_id,:o,product_id,product_name,quantity,unit_price,subtotal,notes from cart_items where cart_id=:c and tenant_id=:t").param("o",id).param("c",c.id()).param("t",t).update();db.sql("insert into order_status_history(id,tenant_id,order_id,status,changed_by) values(gen_random_uuid(),:t,:o,'PENDING',:u)").param("t",t).param("o",id).param("u",customer).update();return order(t,customer,id);}
 public void snapshotOrderItems(UUID t,UUID order,UUID cart){db.sql("delete from order_items where tenant_id=:t and order_id=:o").param("t",t).param("o",order).update();db.sql("insert into order_items(id,tenant_id,order_id,product_id,product_name,quantity,base_unit_price,options_total,unit_price,subtotal,notes) select id,tenant_id,:o,product_id,product_name,quantity,base_unit_price,options_total,unit_price,subtotal,notes from cart_items where tenant_id=:t and cart_id=:c").param("o",order).param("t",t).param("c",cart).update();db.sql("insert into order_item_options(tenant_id,order_item_id,option_group_id,option_item_id,group_name,item_name,price_adjustment) select tenant_id,cart_item_id,option_group_id,option_item_id,group_name,item_name,price_adjustment from cart_item_options where tenant_id=:t and cart_item_id in(select id from cart_items where tenant_id=:t and cart_id=:c)").param("t",t).param("c",cart).update();}
 public List<Order> orders(UUID t,UUID c){return db.sql("select * from orders where tenant_id=:t and customer_id=:c order by created_at desc").param("t",t).param("c",c).query((r,n)->mapOrder(r,t,c)).list();}
 public Order order(UUID t,UUID c,UUID id){return db.sql("select * from orders where id=:i and tenant_id=:t and customer_id=:c").param("i",id).param("t",t).param("c",c).query((r,n)->mapOrder(r,t,c)).optional().orElseThrow(()->missing("ORDER_NOT_FOUND","Pedido no encontrado"));}
 public void updateStatus(UUID t,UUID c,UUID id,OrderStatus status,String notes){int n=db.sql("update orders set status=:s,updated_at=now() where id=:i and tenant_id=:t and customer_id=:c").param("s",status.name()).param("i",id).param("t",t).param("c",c).update();if(n==0)throw missing("ORDER_NOT_FOUND","Pedido no encontrado");db.sql("insert into order_status_history(id,tenant_id,order_id,status,notes,changed_by) values(gen_random_uuid(),:t,:o,:s,:n,:u)").param("t",t).param("o",id).param("s",status.name()).param("n",notes).param("u",c).update();}
 public void checkoutCart(UUID t,UUID c){db.sql("update carts set status='CHECKED_OUT',updated_at=now() where id=:c and tenant_id=:t").param("c",c).param("t",t).update();}
 public void audit(UUID t,UUID u,String action,String type,UUID id){db.sql("insert into audit_logs(tenant_id,user_id,action,entity_type,entity_id) values(:t,:u,:a,:y,:i)").param("t",t).param("u",u).param("a",action).param("y",type).param("i",id).update();}
 private Cart mapCart(ResultSet r,UUID t,UUID customer)throws SQLException{UUID id=r.getObject("id",UUID.class);var items=db.sql("select * from cart_items where tenant_id=:t and cart_id=:c order by created_at").param("t",t).param("c",id).query((x,n)->{UUID item=x.getObject("id",UUID.class);return new CartItem(item,id,x.getObject("product_id",UUID.class),x.getString("product_name"),x.getInt("quantity"),x.getBigDecimal("base_unit_price"),x.getBigDecimal("options_total"),x.getBigDecimal("unit_price"),x.getBigDecimal("subtotal"),x.getString("selection_signature"),itemOptions(t,item,"cart_item_options","cart_item_id"),x.getString("notes"),x.getTimestamp("created_at").toInstant());}).list();return new Cart(id,customer,r.getObject("merchant_id",UUID.class),r.getObject("branch_id",UUID.class),r.getBigDecimal("subtotal"),r.getBigDecimal("discount"),r.getBigDecimal("tax"),r.getBigDecimal("delivery_fee"),r.getBigDecimal("total"),r.getString("currency"),r.getString("status"),items,r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant());}
 private List<ItemOption> itemOptions(UUID t,UUID owner,String table,String column){return db.sql("select option_group_id,option_item_id,group_name,item_name,price_adjustment from "+table+" where tenant_id=:t and "+column+"=:i order by created_at").param("t",t).param("i",owner).query((r,n)->new ItemOption(r.getObject("option_group_id",UUID.class),r.getObject("option_item_id",UUID.class),r.getString("group_name"),r.getString("item_name"),r.getBigDecimal("price_adjustment"))).list();}
 private DeliveryAddress mapAddress(ResultSet r)throws SQLException{return new DeliveryAddress(r.getObject("id",UUID.class),r.getString("label"),r.getString("recipient_name"),r.getString("phone"),r.getString("address_line"),r.getString("district"),r.getString("province"),r.getString("department"),r.getString("country_code"),r.getString("postal_code"),r.getBigDecimal("latitude"),r.getBigDecimal("longitude"),r.getString("reference"),r.getBoolean("active"));}
 private Order mapOrder(ResultSet r,UUID t,UUID customer)throws SQLException{UUID id=r.getObject("id",UUID.class);var items=db.sql("select * from order_items where tenant_id=:t and order_id=:o order by id").param("t",t).param("o",id).query((x,n)->{UUID item=x.getObject("id",UUID.class);return new OrderItem(item,id,x.getObject("product_id",UUID.class),x.getString("product_name"),x.getInt("quantity"),x.getBigDecimal("base_unit_price"),x.getBigDecimal("options_total"),x.getBigDecimal("unit_price"),x.getBigDecimal("subtotal"),itemOptions(t,item,"order_item_options","order_item_id"),x.getString("notes"));}).list();var history=db.sql("select * from order_status_history where tenant_id=:t and order_id=:o order by created_at").param("t",t).param("o",id).query((x,n)->new OrderStatusHistory(x.getObject("id",UUID.class),OrderStatus.valueOf(x.getString("status")),x.getString("notes"),x.getTimestamp("created_at").toInstant())).list();boolean rated=db.sql("select exists(select 1 from order_ratings where tenant_id=:t and customer_id=:c and order_id=:o)").param("t",t).param("c",customer).param("o",id).query(Boolean.class).single();return new Order(id,r.getString("order_number"),customer,r.getObject("merchant_id",UUID.class),r.getObject("branch_id",UUID.class),r.getObject("delivery_address_id",UUID.class),OrderStatus.valueOf(r.getString("status")),r.getString("payment_status"),r.getBigDecimal("subtotal"),r.getBigDecimal("discount"),r.getBigDecimal("tax"),r.getBigDecimal("delivery_fee"),r.getBigDecimal("total"),r.getString("currency"),r.getString("notes"),items,history,rated,r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant());}
 private ApiException missing(String code,String message){return new ApiException(HttpStatus.NOT_FOUND,code,message);}
}
